const D = { energy:.6, density:.5, speed:1, scale:1, cohesion:1.0, separation:1.6, alignment:1.0, reach:.5, wander:.4, attract:.45, trail:.5, hue:28, x:.5, y:.5, style:'dusk-flock', act:'murmur', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height), key = width+'x'+height, st = P.style, ga = Math.max(0, P.alpha)/100;
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };

// ── graded sky / ground buffer (rebuilt only on style/hue/seed/size change) ──
const SW = Math.min(240, Math.max(80, Math.round(width/4)));
const SH = Math.max(48, Math.round(SW*height/Math.max(1,width)));
const skyKey = st+'|'+Math.round(P.hue)+'|'+(P.seed|0)+'|'+SW+'x'+SH;
if (S.skyKey !== skyKey) {
  S.skyKey = skyKey; S.needEstab = true;
  let g2 = S.sky;
  if (!g2 || S.skW!==SW || S.skH!==SH) { g2 = S.sky = createGraphics(SW, SH); g2.pixelDensity(1); S.skW=SW; S.skH=SH; }
  g2.colorMode(g2.HSB, 360, 100, 100, 100);
  g2.noStroke();
  if (st === 'ink-silhouette') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); g2.fill(38, 9, 91 - ty*9); g2.rect(0,jy,SW,1); }
    for (let k=0;k<240;k++){ const gx=fr(k*2+1)*SW, gy=fr(k*2+2)*SH; g2.fill(34, 16, 66, 16); const rr=1+fr(k*3+5)*2.2; g2.ellipse(gx,gy,rr,rr); }
  } else if (st === 'neon-vector') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); g2.fill((P.hue+200)%360, 60, 3+ty*4); g2.rect(0,jy,SW,1); }
  } else if (st === 'thermal-density') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); g2.fill(245, 48, 2+ty*3.5); g2.rect(0,jy,SW,1); }
  } else if (st === 'blueprint-vectors') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); g2.fill(212, 62, 8+ty*4); g2.rect(0,jy,SW,1); }
    g2.stroke(200, 45, 45, 24); g2.strokeWeight(1);
    const gs = SW/14;
    for (let gx=gs; gx<SW; gx+=gs) g2.line(gx,0,gx,SH);
    for (let gy=gs; gy<SH; gy+=gs) g2.line(0,gy,SW,gy);
    g2.noStroke();
  } else { // dusk-flock — graded dusk sky + sun glow
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); const tt=ty*ty*(3-2*ty);
      const h=((P.hue+205+tt*155)%360+360)%360; g2.fill(h, 42+ty*32, 24+tt*30); g2.rect(0,jy,SW,1); }
    g2.blendMode(g2.ADD);
    const sx=P.x*SW, sy=0.75*SH;
    for (let r=0;r<6;r++){ const rr=(0.62-r*0.09)*SW; g2.fill((P.hue+16)%360, 62, 72, 8); g2.ellipse(sx, sy, rr, rr*0.7); }
    g2.blendMode(g2.BLEND);
  }
}

// ── population (rebuilt only on seed / size / count change) ──
const N = Math.floor(180 + P.density*440);
if (S.seedUsed!==P.seed || S.pkey!==key || !S.ps || S.ps.length!==N){
  S.seedUsed=P.seed; S.pkey=key;
  let z=(P.seed*2654435761+12345)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.ps=[];
  for (let i=0;i<N;i++){ const a=S.rnd()*6.2832;
    S.ps.push({ x:S.rnd()*width, y:S.rnd()*height, vx:Math.cos(a)*(0.4+S.rnd()*0.6), vy:Math.sin(a)*(0.4+S.rnd()*0.6) }); }
}
const ps=S.ps, rnd=S.rnd;

// ── arc + acts (30s–5min; never re-phases — K.t / K.section driven) ──
const intn = (K.intensity!=null?K.intensity:0.6);
const sweep = 0.5 + 0.5*Math.sin(K.section*0.8 + K.t*0.012);   // laminar ↔ splitting
const cohMul = 0.7 + sweep*0.7 + K.swell*0.3;
const sepMul = 1.18 - sweep*0.34;
const spdMul = 0.82 + intn*0.5;
let followK = 0.0022 + P.attract*0.006;
let sepSpike = 1;
if (P.act==='startle'){ sepSpike = 1 + (K.pulse*1.6 + A.bass*1.3); }
else if (P.act==='settle'){ followK *= 1.9; }
// wandering global attractor — homes at P.x,P.y, roves on real time (no re-phase)
const atx = ((P.x + 0.30*Math.sin(K.t*0.041 + 1.3)) % 1 + 1) % 1 * width;
const aty = ((P.y + 0.24*Math.sin(K.t*0.033 + 0.7)) % 1 + 1) % 1 * height;

// ── steering constants (resolution-relative) ──
const rad = u*(0.032 + P.reach*0.11) * P.scale, rad2 = rad*rad;
const sepR2 = (rad*0.5)*(rad*0.5);
const vmax = u*(0.0035 + P.speed*0.008) * spdMul, vmin = vmax*0.18;
const wCoh = (0.30 + P.cohesion*1.0) * cohMul;
const wAli = 0.35 + P.alignment*1.25;
const wSep = (0.60 + P.separation*1.6) * sepMul * sepSpike;
const wanderAmt = vmax*(0.05 + P.wander*0.5);
const forceCap = vmax*0.9;
const hw=width*0.5, hh=height*0.5;
const hueDrift = K.t*7;

// ── spatial hash (cell = neighbor radius; reused buckets → O(N·k)) ──
const cell=Math.max(6,rad), cols=Math.max(1,Math.ceil(width/cell)), rows=Math.max(1,Math.ceil(height/cell));
let grid=S.grid;
if (!grid || S.gc!==cols || S.gr!==rows){ grid=S.grid=new Array(cols*rows); S.gc=cols; S.gr=rows; for (let i=0;i<grid.length;i++) grid[i]=[]; }
for (let i=0;i<grid.length;i++) grid[i].length=0;
const cellOf=(x,y)=>((((Math.floor(x/cell)%cols)+cols)%cols) + (((Math.floor(y/cell)%rows)+rows)%rows)*cols);
for (let i=0;i<N;i++){ const p=ps[i]; grid[cellOf(p.x,p.y)].push(i); }

// ── fade toward the sky/ground buffer (motion-blur trails) ──
const fadeA = (8 + P.trail*34) * ga;
blendMode(BLEND);
noStroke();
tint(0,0,100, S.needEstab ? 100 : fadeA);
image(S.sky, 0, 0, width, height);
noTint();
S.needEstab = false;

const additive = (st==='neon-vector' || st==='thermal-density');
blendMode(additive ? ADD : BLEND);

// ── one pass: neighbor sums (hash) → steer → integrate → draw ──
for (let i=0;i<N;i++){
  const p=ps[i];
  const cx=(((Math.floor(p.x/cell)%cols)+cols)%cols), cy=(((Math.floor(p.y/cell)%rows)+rows)%rows);
  let sx=0,sy=0, ax=0,ay=0, gx=0,gy=0, cnt=0, lc=0;
  for (let ox=-1;ox<=1;ox++) for (let oy=-1;oy<=1;oy++){
    const b=grid[((((cx+ox)%cols)+cols)%cols) + (((((cy+oy)%rows)+rows)%rows)*cols)];
    for (let k=0;k<b.length;k++){
      const j=b[k]; if (j===i) continue; const q=ps[j];
      let dx=q.x-p.x, dy=q.y-p.y;
      if (dx>hw)dx-=width; else if (dx<-hw)dx+=width;
      if (dy>hh)dy-=height; else if (dy<-hh)dy+=height;
      const d2=dx*dx+dy*dy; if (d2>rad2||d2<1e-4) continue;
      gx+=dx; gy+=dy; ax+=q.vx; ay+=q.vy;
      if (d2<sepR2){ const inv=1/d2; sx-=dx*inv; sy-=dy*inv; }
      cnt++;
      if (st==='blueprint-vectors' && lc<2 && j>i && d2<rad2*0.34){ stroke(200,50,80,22*ga); strokeWeight(0.7); line(p.x,p.y,p.x+dx,p.y+dy); lc++; }
    }
  }
  let accx=0, accy=0;
  if (cnt>0){ const inv=1/cnt;
    accx += gx*inv*wCoh*0.02 + ((ax*inv)-p.vx)*wAli*0.35 + sx*wSep*3.0;
    accy += gy*inv*wCoh*0.02 + ((ay*inv)-p.vy)*wAli*0.35 + sy*wSep*3.0;
  }
  let adx=atx-p.x; if (adx>hw)adx-=width; else if (adx<-hw)adx+=width;
  let ady=aty-p.y; if (ady>hh)ady-=height; else if (ady<-hh)ady+=height;
  accx += adx*followK; accy += ady*followK;
  const wa = noise(p.x*0.0016, p.y*0.0016, K.t*0.045 + S.seedUsed*0.017)*12.566;
  accx += Math.cos(wa)*wanderAmt; accy += Math.sin(wa)*wanderAmt;
  const am=Math.hypot(accx,accy); if (am>forceCap){ const s=forceCap/am; accx*=s; accy*=s; }
  p.vx+=accx; p.vy+=accy;
  let sp=Math.hypot(p.vx,p.vy);
  if (sp>vmax){ const s=vmax/sp; p.vx*=s; p.vy*=s; sp=vmax; }
  else if (sp<vmin && sp>1e-4){ const s=vmin/sp; p.vx*=s; p.vy*=s; sp=vmin; }
  if (!isFinite(p.x)||!isFinite(p.y)||!isFinite(p.vx)||!isFinite(p.vy)){ p.x=rnd()*width; p.y=rnd()*height; p.vx=rnd()-0.5; p.vy=rnd()-0.5; sp=vmin; }
  p.x=(p.x+p.vx+width)%width; p.y=(p.y+p.vy+height)%height;

  const sn=Math.min(1, sp/(vmax||1));
  if (st==='dusk-flock'){
    const h=(P.hue + 272 + sn*100 + hueDrift)%360;
    stroke((h+360)%360, 55+sn*35, Math.min(100, 34+sn*56+A.rms*20), (46+P.energy*30)*ga);
    strokeWeight((0.9+P.energy*1.4+sn*0.8)*P.scale);
    const tl=2.4+P.energy*4+sn*3; line(p.x,p.y, p.x-p.vx*tl, p.y-p.vy*tl);
  } else if (st==='neon-vector'){
    const hd=Math.atan2(p.vy,p.vx);
    const h=((P.hue + hueDrift + hd*28)%360+360)%360;
    const al=Math.min(32, (12+P.energy*16+K.pulse*6)*ga);
    stroke(h, 82, Math.min(100, 60+sn*40+A.rms*40), al);
    strokeWeight((0.8+P.energy*1.5)*P.scale);
    const tl=2.5+P.energy*4; line(p.x,p.y, p.x-p.vx*tl, p.y-p.vy*tl);
  } else if (st==='thermal-density'){
    const dens=Math.min(1, cnt/14);
    const h=((240 - sn*240)%360+360)%360;
    const al=Math.min(30, (10+P.energy*13+dens*10)*ga);
    stroke(h, 85-dens*30, Math.min(100, 45+sn*38+dens*25+A.rms*30), al);
    strokeWeight((1.0+P.energy*1.5+dens*1.2)*P.scale);
    const tl=2.2+P.energy*3.4; line(p.x,p.y, p.x-p.vx*tl, p.y-p.vy*tl);
  } else if (st==='blueprint-vectors'){
    const sp2=Math.max(1e-3, sp);
    stroke(196, 55, 92, 66*ga); strokeWeight(1.0*P.scale);
    const vl=(4+sn*11)*P.scale; line(p.x,p.y, p.x+(p.vx/sp2)*vl, p.y+(p.vy/sp2)*vl);
    noStroke(); fill(190, 42, 96, 80*ga); const nr=2.1*P.scale; ellipse(p.x,p.y,nr,nr);
  } else { // ink-silhouette
    const jj=fr(i);
    if (sn>0.5){ stroke(28, 16, 10+jj*8, (18+jj*28)*ga); strokeWeight((0.8+jj)*P.scale); const tl=2+sn*3; line(p.x,p.y, p.x-p.vx*tl, p.y-p.vy*tl); }
    noStroke(); fill(28, 14, 8+jj*7, (30+jj*44)*ga); const r=(1.4+jj*2.2+P.energy*1.5)*P.scale; ellipse(p.x,p.y,r,r);
  }
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0;
